        text: "ウ：符号の差の解釈は適切だが，中央値の回答が誤り。「使いやすい」は8〜10番目の3人であり，中央の5番目・6番目には当たらない。"
      },
      {
        type: "text",
        text: "エ：中央値の回答と，符号の差の解釈の双方が誤り。中央の回答は「ふつう」であり，符号の差から使いやすさの差の大きさまでは読み取れない。"
      },
      {
        type: "text",
        text: "順序尺度の性質と中央値の定義を基に作成した問題であり，表は自作である。"
      }
    ],
    source_text: "文部科学省『高等学校情報科「情報Ⅰ」教員研修用教材（本編）』第4章，学習22「量的データの分析」（1）「量的データと質的データ」，本文184〜185頁（PDF32〜33ページ） | https://www.mext.go.jp/content/20200722-mxt_jogai02-100013300_006.pdf#page=32\n総務省統計局「なるほど統計学園／中心的な傾向を捉える」中央値 | https://www.stat.go.jp/naruhodo/5_tokucho/chushin.html"
  }
]

unless questions.map { |question| question.fetch(:question_number) } == (1..20).to_a
  raise "模擬試験36は問1〜20の20問で構成してください"
end
expected_categories = ["education_foundations", "education_foundations", "education_system", "education_system", "education_system", "curriculum_organization", "career_education", "integrated_inquiry", "moral_education", "special_activities", "student_guidance_career", "special_support_education", "educational_psychology", "educational_psychology", "education_system", "information_specialized", "information_education", "information_specialized", "information_specialized", "information_specialized"]
unless questions.map { |question| question.fetch(:category_code) } == expected_categories
  raise "模擬試験36の分類・問題順が不正です"
end
expected_blank_counts = { 4 => 4, 5 => 4, 6 => 4, 7 => 3, 8 => 4, 9 => 4, 10 => 4, 11 => 3, 16 => 4, 17 => 4, 18 => 3 }
questions.each do |question|
  number = question.fetch(:question_number)
  unless question.fetch(:major_category_code) == (number <= 15 ? "teacher_education" : "information")
    raise "問#{number}の大分類が不正です"
  end
  if [6, 7].include?(number)
    clause = number == 6 ? "第3款" : "第5款"
    unless question.fetch(:content_blocks).first.fetch(:text).include?(clause) && question.fetch(:source_text).include?(clause)
      raise "問#{number}の総則の出典範囲が不正です"
    end
  end
  choices = question.fetch(:choices)
  unless choices.map { |choice| choice.fetch(:label) } == %w[ア イ ウ エ] && choices.count { |choice| choice.fetch(:correct) } == 1 && choices.map { |choice| choice.fetch(:content_blocks) }.uniq.size == 4
    raise "問#{number}は異なる4択・正答1件にしてください"
  end
  texts = question.fetch(:explanation_blocks).filter_map { |block| block[:text] }
  unless %w[ア イ ウ エ].all? { |label| texts.any? { |text| text.start_with?("#{label}：") } }
    raise "問#{number}は全肢解説が必要です"
  end
  sources = question.fetch(:source_text).lines.map(&:strip)
  unless sources.any? && sources.all? { |line| line.match?(/\A.+ \| https:\/\/\S+\z/) }
    raise "問#{number}の出典形式が不正です"
  end
  blocks = question.fetch(:content_blocks)
  quotes = blocks.select { |block| block[:type] == "fill_in_quote" }
  text_labels = blocks.flat_map { |block| block.fetch(:text, "").scan(/\{\{([^{}]+)\}\}/).flatten }.uniq.sort
  count = expected_blank_counts[number]
  if count
    labels = %w[① ② ③ ④].first(count)
    body_labels = if 36 == 40 && number == 11
      blocks.select { |block| block[:type] == "table" }.flat_map do |block|
        (block.fetch(:headers) + block.fetch(:rows).flatten).flat_map { |cell| cell.scan(/【([^】]+)】/).flatten }
      end.uniq.sort
    else
      quotes.flat_map { |block| block.fetch(:text).scan(/\{\{([^{}]+)\}\}/).flatten }.uniq.sort
    end
    unless blocks.first[:type] == "fill_in_text" && text_labels == labels && body_labels == labels &&
        choices.all? { |choice| choice[:content_blocks].size == 1 && choice[:content_blocks].first[:type] == "fill_in_choice" && choice[:content_blocks].first[:cells].size == count }
      raise "問#{number}の必須空欄・選択肢の対応が不正です"
    end
    if (4..5).cover?(number) && !quotes.all? { |quote| quote.fetch(:text).match?(/\A第\d+条/) }
      raise "問#{number}の抜粋枠は条番号から始めてください"
    end
    choices.map { |choice| choice[:content_blocks].first[:cells] }.transpose.each do |column|
      raise "問#{number}の空欄候補は各列2対2にしてください" unless column.tally.values.sort == [2, 2]
    end
  elsif text_labels.any? || choices.any? { |choice| choice[:content_blocks].any? { |block| block[:type] == "fill_in_choice" } }
    raise "問#{number}に想定外の空欄があります"
  end
  if number == 19
    code = blocks.select { |block| block[:type] == "code" }
    labels = code.flat_map { |block| block.fetch(:code).scan(/【([^】]+)】/).flatten }.uniq
    unless code.size == 1 && labels == ([36, 38, 40].include?(36) ? %w[①] : []) && code.none? { |block| block[:code].include?("{{") }
      raise "問19のコードと空欄が不正です"
    end
  end
  blocks.select { |block| block[:type] == "table" }.each do |block|
    if (block.fetch(:headers) + block.fetch(:rows).flatten).any? { |cell| cell.include?("{{") }
      raise "表の空欄は【①】のように表示してください"
    end
  end
end
unless questions.map { |question| question.fetch(:choices).find { |choice| choice[:correct] }.fetch(:label) }.tally == { "ア" => 5, "イ" => 5, "ウ" => 5, "エ" => 5 }
  raise "模擬試験36の正答位置は各5件にしてください"
end
information_ranges = questions.select { |question| (16..18).cover?(question[:question_number]) }.map do |question|
  prompt = question.fetch(:content_blocks).first.fetch(:text)
  source = question.fetch(:source_text)
  if prompt.include?("解説 情報編") && source.include?("解説 情報編")
    prompt.include?("第1部") && source.include?("第1部") ? 3 : prompt.include?("第2部") && source.include?("第2部") ? 4 : nil
  elsif prompt.include?("第2章") && prompt.include?("第10節") && source.include?("第2章") && source.include?("第10節")
    1
  elsif prompt.include?("第3章") && prompt.include?("第7節") && source.include?("第3章") && source.include?("第7節")
    2
  end
end
unless information_ranges == [1, 2, 3]
  raise "模擬試験36の問16〜18は異なる3資料範囲を資料・項目順にしてください"
end
QuestionSeedSync.import(exam_number: 36, questions: questions, publication_status: "published")
